    # If all trees are already colored but beauty doesn't match k, impossible.
    # We will handle these cases within the DP logic by checking feasibility.

    # dp[i][j][cnt] = minimum cost to color first i trees such that:
    # tree i has color j (1-based), and there are 'cnt' groups so far.
    # i ranges from 0 to n-1 (0-indexed trees)
    # j ranges from 1 to m
    # cnt ranges from 1 to k

    # Initialize with infinity
    INF = float('inf')

    # We can optimize space, but given constraints (n, m, k <= 100), O(n*m*k) is fine.
    # Dimensions: dp[n][m+1][k+1]

    # To save memory and time in Python, we can use a flat list or nested lists carefully.
    # Let's use a 3D list.

    # Initialize dp table
    # dp[i][color][groups]
    # i: 0..n-1
    # color: 1..m
    # groups: 1..k

    dp = [[[INF] * (k + 1) for _ in range(m + 1)] for _ in range(n)]

    # Base case: first tree (index 0)
    color_val = c[0]

    for j in range(1, m + 1):
        # If the first tree is already colored and color != j, we can't choose j
        if color_val != 0 and color_val != j:
            continue

        cost = 0
        if color_val == 0:
            cost = p[0][j-1]

        # If the first tree is colored with color j, cost is 0.
        # If it was uncolored and we chose j, cost is p[0][j-1].
        # If it was uncolored and we chose something else, handled by loop.

        if color_val != 0 and color_val != j:
            continue # Should not happen due to check above, but for safety

        if color_val == 0:
            cost = p[0][j-1]

        # First tree always forms the 1st group
        dp[0][j][1] = cost

    # Iterate through the rest of the trees
    for i in range(1, n):
        current_color_constraint = c[i]

        for j in range(1, m + 1): # Current tree color j
            if current_color_constraint != 0 and current_color_constraint != j:
                continue

            cost_add = 0
            if current_color_constraint == 0:
                cost_add = p[i][j-1]

            # Try to transition from previous tree (i-1)
            # Previous tree could have any color 'prev_j'
            # If prev_j == j, same group, groups count stays same.
            # If prev_j != j, new group, groups count increases by 1.

            for prev_groups in range(1, k + 1):
                # Case 1: Same color as previous tree (if possible)
                # We need to find min dp[i-1][j][prev_groups]
                if prev_groups <= k:
                    best_same = INF
