                    # We need to iterate prev_j which is j
                    if dp[i-1][j][prev_groups] != INF:
                        best_same = dp[i-1][j][prev_groups]

                    if best_same != INF:
                        if prev_groups < k:
                            new_val = best_same + cost_add
                            if new_val < dp[i][j][prev_groups + 1]:
                                dp[i][j][prev_groups + 1] = new_val
                        else:
                            new_val = best_same + cost_add
                            if new_val < dp[i][j][prev_groups]:
                                dp[i][j][prev_groups] = new_val

